import type { StateCreator } from 'zustand';
import type { ViewMode, CameraPreset } from '../types/editor';

export interface UISlice {
  viewMode: ViewMode;
  cameraPreset: CameraPreset;
  showGrid: boolean;
  showConstraints: boolean;
  showPropertyPanel: boolean;

  setViewMode: (mode: ViewMode) => void;
  toggleViewMode: () => void;
  setCameraPreset: (preset: CameraPreset) => void;
  toggleGrid: () => void;
  toggleConstraints: () => void;
  togglePropertyPanel: () => void;
}

export const createUISlice: StateCreator<UISlice & Record<string, unknown>, [], [], UISlice> = (set, get) => ({
  viewMode: '2d',
  cameraPreset: 'isometric',
  showGrid: true,
  showConstraints: true,
  showPropertyPanel: false,

  setViewMode: (mode) => set({ viewMode: mode }),
  toggleViewMode: () => set({ viewMode: get().viewMode === '2d' ? '3d' : '2d' }),
  setCameraPreset: (preset) => set({ cameraPreset: preset }),
  toggleGrid: () => set({ showGrid: !get().showGrid }),
  toggleConstraints: () => set({ showConstraints: !get().showConstraints }),
  togglePropertyPanel: () => set({ showPropertyPanel: !get().showPropertyPanel }),
});
