import type { Point, WalkNode, Grid } from '../types';
import { distance, snapPointToGrid, snapAngle, polarToCartesian } from '../utils/math';
import { SNAP_RADIUS } from '../utils/constants';

export type SnapGuide =
  | { type: 'gridLine'; axis: 'x' | 'y'; value: number }
  | { type: 'angleLine'; from: Point; to: Point; angleDeg: number }
  | { type: 'proximityCircle'; center: Point; radius: number };

export interface SnapConfig {
  gridSnap: boolean;
  angleSnap: boolean;
  nearNodeSnap: boolean;
}

export interface SnapContext {
  grid: Grid;
  nodes: WalkNode[];
  origin?: Point;      // for angle snap (e.g., start of edge drawing)
}

export interface SnapResult {
  point: Point;
  guides: SnapGuide[];
  snappedTo: 'grid' | 'angle' | 'node' | 'none';
}

export function applySnap(raw: Point, config: SnapConfig, ctx: SnapContext): SnapResult {
  const guides: SnapGuide[] = [];
  let point = { ...raw };
  let snappedTo: SnapResult['snappedTo'] = 'none';

  // 1. Near-node snap (highest priority)
  if (config.nearNodeSnap) {
    let closest: WalkNode | null = null;
    let closestDist = SNAP_RADIUS;
    for (const node of ctx.nodes) {
      const d = distance(raw, node);
      if (d < closestDist) {
        closest = node;
        closestDist = d;
      }
    }
    if (closest) {
      point = { x: closest.x, y: closest.y };
      guides.push({ type: 'proximityCircle', center: point, radius: SNAP_RADIUS });
      snappedTo = 'node';
      return { point, guides, snappedTo };
    }
  }

  // 2. Angle snap
  if (config.angleSnap && ctx.origin && ctx.grid.angleStepDeg) {
    const dx = raw.x - ctx.origin.x;
    const dy = raw.y - ctx.origin.y;
    const rawAngle = Math.atan2(dy, dx) * (180 / Math.PI);
    const snappedAngleDeg = snapAngle(rawAngle, ctx.grid.angleStepDeg);
    const dist = distance(ctx.origin, raw);
    point = polarToCartesian(ctx.origin, snappedAngleDeg, dist);
    guides.push({ type: 'angleLine', from: ctx.origin, to: point, angleDeg: snappedAngleDeg });
    snappedTo = 'angle';
  }

  // 3. Grid snap (lowest priority, but always applied if enabled)
  if (config.gridSnap) {
    point = snapPointToGrid(point, ctx.grid.snap);
    guides.push({ type: 'gridLine', axis: 'x', value: point.x });
    guides.push({ type: 'gridLine', axis: 'y', value: point.y });
    if (snappedTo === 'none') snappedTo = 'grid';
  }

  return { point, guides, snappedTo };
}
