import { useStore } from '../../store';

export function ModeToggle() {
  const viewMode = useStore(s => s.viewMode);
  const toggleViewMode = useStore(s => s.toggleViewMode);

  return (
    <button
      onClick={toggleViewMode}
      style={{
        padding: '6px 12px',
        border: 'none',
        borderRadius: 6,
        background: viewMode === '3d' ? '#2563eb' : '#f1f5f9',
        color: viewMode === '3d' ? 'white' : '#334155',
        fontSize: 13,
        fontWeight: 600,
        cursor: 'pointer',
      }}
    >
      {viewMode === '2d' ? '3D' : '2D'}
    </button>
  );
}
