import { memo } from 'react';
import type { SnapGuide } from '../../engine/snap';
import { COLORS } from '../../utils/constants';

interface SnapGuidesProps {
  guides: SnapGuide[];
}

export const SnapGuides = memo(function SnapGuides({ guides }: SnapGuidesProps) {
  return (
    <g>
      {guides.map((guide, i) => {
        switch (guide.type) {
          case 'gridLine':
            return guide.axis === 'x' ? (
              <line key={i} x1={guide.value} y1={-1000} x2={guide.value} y2={1000}
                stroke={COLORS.snap} strokeWidth={0.02} strokeDasharray="0.06 0.04" opacity={0.5} />
            ) : (
              <line key={i} x1={-1000} y1={guide.value} x2={1000} y2={guide.value}
                stroke={COLORS.snap} strokeWidth={0.02} strokeDasharray="0.06 0.04" opacity={0.5} />
            );
          case 'angleLine':
            return (
              <line key={i}
                x1={guide.from.x} y1={guide.from.y} x2={guide.to.x} y2={guide.to.y}
                stroke={COLORS.snap} strokeWidth={0.02} strokeDasharray="0.08 0.04" opacity={0.6} />
            );
          case 'proximityCircle':
            return (
              <circle key={i}
                cx={guide.center.x} cy={guide.center.y} r={guide.radius}
                fill="none" stroke={COLORS.snap} strokeWidth={0.02} opacity={0.4} />
            );
          default:
            return null;
        }
      })}
    </g>
  );
});
