import type { StateCreator } from 'zustand';
import type { EditorTool, SelectionState, DragState, BoxSelectState, ItemPlacementType } from '../types/editor';

export interface EditorSlice {
  activeTool: EditorTool;
  activeFloorId: string;
  selection: SelectionState;
  dragState: DragState;
  boxSelectState: BoxSelectState;
  itemPlacementType: ItemPlacementType;
  snapEnabled: boolean;

  setTool: (tool: EditorTool) => void;
  setActiveFloor: (floorId: string) => void;
  setSelection: (selection: SelectionState) => void;
  clearSelection: () => void;
  toggleNodeSelection: (nodeId: string) => void;
  setDragState: (state: DragState) => void;
  setBoxSelectState: (state: BoxSelectState) => void;
  setItemPlacementType: (type: ItemPlacementType) => void;
  toggleSnap: () => void;
}

const emptySelection: SelectionState = { nodeIds: [], edgeIds: [], itemIds: [] };

export const createEditorSlice: StateCreator<EditorSlice & Record<string, unknown>, [], [], EditorSlice> = (set, get) => ({
  activeTool: 'select',
  activeFloorId: '',  // Will be set when project loads
  selection: { ...emptySelection },
  dragState: null,
  boxSelectState: null,
  itemPlacementType: 'stairs',
  snapEnabled: true,

  setTool: (tool) => set({ activeTool: tool, selection: { ...emptySelection }, dragState: null, boxSelectState: null }),
  setActiveFloor: (floorId) => set({ activeFloorId: floorId, selection: { ...emptySelection } }),
  setSelection: (selection) => set({ selection }),
  clearSelection: () => set({ selection: { ...emptySelection } }),
  toggleNodeSelection: (nodeId) => {
    const current = get().selection;
    const idx = current.nodeIds.indexOf(nodeId);
    if (idx >= 0) {
      set({ selection: { ...current, nodeIds: current.nodeIds.filter((id) => id !== nodeId) } });
    } else {
      set({ selection: { ...current, nodeIds: [...current.nodeIds, nodeId] } });
    }
  },
  setDragState: (state) => set({ dragState: state }),
  setBoxSelectState: (state) => set({ boxSelectState: state }),
  setItemPlacementType: (type) => set({ itemPlacementType: type }),
  toggleSnap: () => set({ snapEnabled: !get().snapEnabled }),
});
