import { useEffect, Suspense, lazy } from 'react';
import { useStore } from './store';
import { Canvas2D } from './components/editor-2d/Canvas2D';
import { Toolbar } from './components/ui/Toolbar';
import { FloorSelector } from './components/ui/FloorSelector';
import { UndoRedoButtons } from './components/ui/UndoRedoButtons';
import { ModeToggle } from './components/ui/ModeToggle';
import { CameraPresetPicker } from './components/ui/CameraPresetPicker';
import { ItemPalette } from './components/ui/ItemPalette';
import { PropertyPanel } from './components/ui/PropertyPanel';
import { scheduleAutosave } from './persistence/autosave';

// Lazy load 3D scene (heavy Three.js bundle)
const Scene3D = lazy(() => import('./components/viewer-3d/Scene3D').then(m => ({ default: m.Scene3D })));

export default function App() {
  const viewMode = useStore(s => s.viewMode);
  const activeFloorId = useStore(s => s.activeFloorId);
  const setActiveFloor = useStore(s => s.setActiveFloor);
  const project = useStore(s => s.project);
  const snapEnabled = useStore(s => s.snapEnabled);
  const toggleSnap = useStore(s => s.toggleSnap);

  // Initialize active floor on first load
  useEffect(() => {
    if (!activeFloorId && project.floors.length > 0) {
      setActiveFloor(project.floors[0]!.id);
    }
  }, [activeFloorId, project.floors, setActiveFloor]);

  // Autosave on project changes
  useEffect(() => {
    scheduleAutosave(project);
  }, [project]);

  return (
    <div style={{
      width: '100vw',
      height: '100dvh',
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      {/* Top Bar */}
      <div style={{
        height: 48,
        display: 'flex',
        alignItems: 'center',
        padding: '0 8px',
        gap: 8,
        background: 'white',
        borderBottom: '1px solid #e2e8f0',
        zIndex: 20,
        flexShrink: 0,
      }}>
        <FloorSelector />
        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <button
            onClick={toggleSnap}
            style={{
              padding: '4px 8px',
              border: 'none',
              borderRadius: 4,
              background: snapEnabled ? '#dbeafe' : '#f1f5f9',
              color: snapEnabled ? '#2563eb' : '#94a3b8',
              fontSize: 11,
              cursor: 'pointer',
              fontWeight: 500,
            }}
            title="Toggle Snap"
          >
            SNAP
          </button>
          <UndoRedoButtons />
          <ModeToggle />
        </div>
      </div>

      {/* Canvas Area */}
      <div style={{ flex: 1, position: 'relative', overflow: 'hidden' }}>
        {viewMode === '2d' ? (
          <Canvas2D />
        ) : (
          <Suspense fallback={
            <div style={{
              width: '100%', height: '100%',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: '#f1f5f9', color: '#64748b',
            }}>
              Loading 3D...
            </div>
          }>
            <Scene3D />
          </Suspense>
        )}

        {/* Overlays */}
        <Toolbar />
        <ItemPalette />
        <CameraPresetPicker />
        <PropertyPanel />
      </div>
    </div>
  );
}
