import { useStore } from '../../store';
import type { CameraPreset } from '../../types/editor';

const presets: Array<{ id: CameraPreset; label: string }> = [
  { id: 'isometric', label: 'ISO' },
  { id: 'perspective', label: 'PERSP' },
  { id: 'top', label: 'TOP' },
];

export function CameraPresetPicker() {
  const viewMode = useStore(s => s.viewMode);
  const cameraPreset = useStore(s => s.cameraPreset);
  const setCameraPreset = useStore(s => s.setCameraPreset);

  if (viewMode !== '3d') return null;

  return (
    <div style={{
      position: 'absolute',
      bottom: 16,
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      gap: 4,
      background: 'white',
      borderRadius: 8,
      padding: 4,
      boxShadow: '0 2px 12px rgba(0,0,0,0.15)',
      zIndex: 10,
    }}>
      {presets.map(p => (
        <button
          key={p.id}
          onClick={() => setCameraPreset(p.id)}
          style={{
            padding: '8px 14px',
            border: 'none',
            borderRadius: 6,
            background: cameraPreset === p.id ? '#2563eb' : 'transparent',
            color: cameraPreset === p.id ? 'white' : '#475569',
            fontSize: 12,
            fontWeight: 600,
            cursor: 'pointer',
          }}
        >
          {p.label}
        </button>
      ))}
    </div>
  );
}
