import { memo } from 'react';
import type { WalkNode } from '../../types';
import type { DragState } from '../../types/editor';
import { COLORS, NODE_RADIUS } from '../../utils/constants';

interface NodeLayerProps {
  nodes: WalkNode[];
  selectedNodeIds: string[];
  dragState: DragState;
}

export const NodeLayer = memo(function NodeLayer({ nodes, selectedNodeIds, dragState }: NodeLayerProps) {
  const selectedSet = new Set(selectedNodeIds);

  return (
    <g>
      {nodes.map(node => {
        const isSelected = selectedSet.has(node.id);
        const isDragging = dragState?.active && dragState.targetId === node.id;
        const x = isDragging ? dragState.currentX : node.x;
        const y = isDragging ? dragState.currentY : node.y;
        const color = COLORS.node[node.kind];

        return (
          <g key={node.id}>
            {isSelected && (
              <circle cx={x} cy={y} r={NODE_RADIUS * 1.8}
                fill="none" stroke={COLORS.selection} strokeWidth={0.04} strokeDasharray="0.08 0.04" />
            )}
            <circle cx={x} cy={y} r={NODE_RADIUS}
              fill={color} stroke="white" strokeWidth={0.04}
              style={{ cursor: 'pointer' }} data-node-id={node.id}
            />
            {node.kind === 'door' && (
              <rect x={x - NODE_RADIUS * 0.5} y={y - NODE_RADIUS * 0.3}
                width={NODE_RADIUS} height={NODE_RADIUS * 0.6}
                fill="white" rx={0.02} />
            )}
          </g>
        );
      })}
    </g>
  );
});
