import { memo, useMemo } from 'react';
import type { WalkNode, WalkEdge } from '../../types';
import { COLORS, EDGE_HIT_WIDTH } from '../../utils/constants';

interface EdgeLayerProps {
  edges: WalkEdge[];
  nodes: WalkNode[];
  selectedEdgeIds: string[];
}

export const EdgeLayer = memo(function EdgeLayer({ edges, nodes, selectedEdgeIds }: EdgeLayerProps) {
  const nodeMap = useMemo(() => new Map(nodes.map(n => [n.id, n])), [nodes]);
  const selectedSet = new Set(selectedEdgeIds);

  return (
    <g>
      {edges.map(edge => {
        const fromNode = nodeMap.get(edge.from);
        const toNode = nodeMap.get(edge.to);
        if (!fromNode || !toNode) return null;

        const isSelected = selectedSet.has(edge.id);
        const color = COLORS.edge[edge.kind];

        return (
          <g key={edge.id}>
            <line
              x1={fromNode.x} y1={fromNode.y} x2={toNode.x} y2={toNode.y}
              stroke="transparent" strokeWidth={EDGE_HIT_WIDTH}
              style={{ cursor: 'pointer' }}
            />
            <line
              x1={fromNode.x} y1={fromNode.y} x2={toNode.x} y2={toNode.y}
              stroke={isSelected ? COLORS.selection : color}
              strokeWidth={isSelected ? 0.08 : 0.06}
              strokeLinecap="round"
            />
            {!edge.bidir && (() => {
              const mx = (fromNode.x + toNode.x) / 2;
              const my = (fromNode.y + toNode.y) / 2;
              const angle = Math.atan2(toNode.y - fromNode.y, toNode.x - fromNode.x) * 180 / Math.PI;
              return (
                <polygon
                  points="-0.12,-0.06 0.06,0 -0.12,0.06"
                  transform={`translate(${mx},${my}) rotate(${angle})`}
                  fill={color}
                />
              );
            })()}
          </g>
        );
      })}
    </g>
  );
});
