import { useRef, useState, useCallback } from 'react';
import { useStore } from '../../store';
import { Grid } from './Grid';
import { NodeLayer } from './NodeLayer';
import { EdgeLayer } from './EdgeLayer';
import { ItemLayer } from './ItemLayer';
import { SelectionOverlay } from './SelectionOverlay';
import { SnapGuides } from './SnapGuides';
import type { Point } from '../../types';
import type { SnapGuide } from '../../engine/snap';
import { applySnap } from '../../engine/snap';
import { createAddNodeCommand, createMoveNodeCommand, createAddEdgeCommand, createAddItemCommand, createMoveSelectionCommand } from '../../engine/commands';
import { createId } from '../../utils/id';
import { NODE_RADIUS } from '../../utils/constants';
import { distance } from '../../utils/math';
import type { AnchorRef } from '../../types/item';

function screenToWorld(
  screenX: number, screenY: number,
  svgEl: SVGSVGElement,
  vb: { x: number; y: number; width: number; height: number },
): Point {
  const rect = svgEl.getBoundingClientRect();
  return {
    x: ((screenX - rect.left) / rect.width) * vb.width + vb.x,
    y: ((screenY - rect.top) / rect.height) * vb.height + vb.y,
  };
}

export function Canvas2D() {
  const svgRef = useRef<SVGSVGElement>(null);
  const [viewBox, setViewBox] = useState({ x: -10, y: -10, width: 20, height: 20 });
  const [snapGuides, setSnapGuides] = useState<SnapGuide[]>([]);
  const [drawingEdge, setDrawingEdge] = useState<{ fromNodeId: string; cursorPos: Point } | null>(null);

  const project = useStore(s => s.project);
  const activeFloorId = useStore(s => s.activeFloorId);
  const activeTool = useStore(s => s.activeTool);
  const selection = useStore(s => s.selection);
  const dragState = useStore(s => s.dragState);
  const boxSelectState = useStore(s => s.boxSelectState);
  const snapEnabled = useStore(s => s.snapEnabled);
  const itemPlacementType = useStore(s => s.itemPlacementType);
  const applyCommand = useStore(s => s.applyCommand);
  const setSelection = useStore(s => s.setSelection);
  const clearSelection = useStore(s => s.clearSelection);
  const setDragState = useStore(s => s.setDragState);
  const setBoxSelectState = useStore(s => s.setBoxSelectState);

  const floorNodes = project.nodes.filter(n => n.floorId === activeFloorId);
  const floorNodeIds = new Set(floorNodes.map(n => n.id));
  const floorEdges = project.links.filter(e => floorNodeIds.has(e.from) || floorNodeIds.has(e.to));
  const floorItems = project.items.filter(i => i.floorId === activeFloorId);

  const getWorldPos = useCallback((e: React.PointerEvent): Point => {
    if (!svgRef.current) return { x: 0, y: 0 };
    return screenToWorld(e.clientX, e.clientY, svgRef.current, viewBox);
  }, [viewBox]);

  const getSnappedPos = useCallback((raw: Point) => {
    if (!snapEnabled) return { point: raw, guides: [] as SnapGuide[] };
    const result = applySnap(raw,
      { gridSnap: true, angleSnap: false, nearNodeSnap: true },
      { grid: project.grid, nodes: floorNodes },
    );
    return { point: result.point, guides: result.guides };
  }, [snapEnabled, project.grid, floorNodes]);

  const findNodeAt = useCallback((pos: Point) => {
    return floorNodes.find(n => distance(pos, n) < NODE_RADIUS * 2);
  }, [floorNodes]);

  // Pan state
  const panRef = useRef({ lastX: 0, lastY: 0, isPanning: false });
  const pinchRef = useRef<{ initialDist: number; initialVB: typeof viewBox } | null>(null);

  const handlePointerDown = useCallback((e: React.PointerEvent) => {
    const worldPos = getWorldPos(e);

    if (activeTool === 'pan') {
      panRef.current = { lastX: e.clientX, lastY: e.clientY, isPanning: true };
      (e.target as Element).setPointerCapture(e.pointerId);
      return;
    }

    if (activeTool === 'select') {
      const node = findNodeAt(worldPos);
      if (node) {
        setDragState({
          active: true,
          startX: worldPos.x, startY: worldPos.y,
          currentX: worldPos.x, currentY: worldPos.y,
          targetId: node.id, targetType: 'node',
        });
        if (!selection.nodeIds.includes(node.id)) {
          setSelection({ nodeIds: [node.id], edgeIds: [], itemIds: [] });
        }
        (e.target as Element).setPointerCapture(e.pointerId);
      } else {
        clearSelection();
        setBoxSelectState({ active: true, startX: worldPos.x, startY: worldPos.y, endX: worldPos.x, endY: worldPos.y });
        (e.target as Element).setPointerCapture(e.pointerId);
      }
      return;
    }

    if (activeTool === 'addNode') {
      const { point } = getSnappedPos(worldPos);
      applyCommand(createAddNodeCommand({
        id: createId(), floorId: activeFloorId,
        x: point.x, y: point.y, kind: 'path',
      }));
      setSnapGuides([]);
      return;
    }

    if (activeTool === 'drawEdge') {
      const node = findNodeAt(worldPos);
      if (!drawingEdge) {
        if (node) setDrawingEdge({ fromNodeId: node.id, cursorPos: worldPos });
      } else {
        if (node && node.id !== drawingEdge.fromNodeId) {
          applyCommand(createAddEdgeCommand({
            id: createId(), from: drawingEdge.fromNodeId, to: node.id,
            floorId: activeFloorId, kind: 'walk', bidir: true,
          }));
        }
        setDrawingEdge(null);
        setSnapGuides([]);
      }
      return;
    }

    if (activeTool === 'addItem') {
      const { point } = getSnappedPos(worldPos);
      const anchor: AnchorRef = { type: 'coordinate', floorId: activeFloorId, x: point.x, y: point.y };
      if (itemPlacementType === 'stairs') {
        applyCommand(createAddItemCommand({
          id: createId(), type: 'stairs', floorId: activeFloorId, anchor,
        }));
      } else {
        applyCommand(createAddItemCommand({
          id: createId(), type: 'elevator', shaftId: createId(), floorId: activeFloorId, anchor,
        }));
      }
      setSnapGuides([]);
      return;
    }
  }, [activeTool, getWorldPos, getSnappedPos, findNodeAt, activeFloorId, selection, drawingEdge, itemPlacementType, applyCommand, setSelection, clearSelection, setDragState, setBoxSelectState]);

  const handlePointerMove = useCallback((e: React.PointerEvent) => {
    const worldPos = getWorldPos(e);

    if (activeTool === 'pan' && panRef.current.isPanning) {
      const svgRect = svgRef.current?.getBoundingClientRect();
      if (!svgRect) return;
      const dx = (e.clientX - panRef.current.lastX) * (viewBox.width / svgRect.width);
      const dy = (e.clientY - panRef.current.lastY) * (viewBox.height / svgRect.height);
      setViewBox(v => ({ ...v, x: v.x - dx, y: v.y - dy }));
      panRef.current.lastX = e.clientX;
      panRef.current.lastY = e.clientY;
      return;
    }

    if (dragState?.active && dragState.targetId) {
      const { point, guides } = getSnappedPos(worldPos);
      setDragState({ ...dragState, currentX: point.x, currentY: point.y });
      setSnapGuides(guides);
      return;
    }

    if (boxSelectState?.active) {
      setBoxSelectState({ ...boxSelectState, endX: worldPos.x, endY: worldPos.y });
      return;
    }

    if (drawingEdge) {
      const { point, guides } = getSnappedPos(worldPos);
      setDrawingEdge({ ...drawingEdge, cursorPos: point });
      setSnapGuides(guides);
    }
  }, [activeTool, viewBox, dragState, boxSelectState, drawingEdge, getWorldPos, getSnappedPos, setDragState, setBoxSelectState]);

  const handlePointerUp = useCallback(() => {
    if (activeTool === 'pan') {
      panRef.current.isPanning = false;
      return;
    }

    if (dragState?.active && dragState.targetId && dragState.targetType === 'node') {
      const dx = dragState.currentX - dragState.startX;
      const dy = dragState.currentY - dragState.startY;
      if (Math.abs(dx) > 0.01 || Math.abs(dy) > 0.01) {
        if (selection.nodeIds.length > 1 && selection.nodeIds.includes(dragState.targetId)) {
          applyCommand(createMoveSelectionCommand(selection.nodeIds, dx, dy));
        } else {
          applyCommand(createMoveNodeCommand(dragState.targetId, dragState.currentX, dragState.currentY));
        }
      }
      setDragState(null);
      setSnapGuides([]);
      return;
    }

    if (boxSelectState?.active) {
      const x1 = Math.min(boxSelectState.startX, boxSelectState.endX);
      const x2 = Math.max(boxSelectState.startX, boxSelectState.endX);
      const y1 = Math.min(boxSelectState.startY, boxSelectState.endY);
      const y2 = Math.max(boxSelectState.startY, boxSelectState.endY);

      const selectedNodes = floorNodes.filter(n => n.x >= x1 && n.x <= x2 && n.y >= y1 && n.y <= y2);
      const selectedNodeIds = selectedNodes.map(n => n.id);
      const nodeIdSet = new Set(selectedNodeIds);
      const selectedEdges = floorEdges.filter(e => nodeIdSet.has(e.from) && nodeIdSet.has(e.to));

      setSelection({ nodeIds: selectedNodeIds, edgeIds: selectedEdges.map(e => e.id), itemIds: [] });
      setBoxSelectState(null);
    }
  }, [activeTool, dragState, boxSelectState, floorNodes, floorEdges, applyCommand, setDragState, setBoxSelectState, setSelection]);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault();
    const factor = e.deltaY > 0 ? 1.1 : 0.9;
    if (!svgRef.current) return;
    const wp = screenToWorld(e.clientX, e.clientY, svgRef.current, viewBox);
    setViewBox(v => ({
      x: wp.x - (wp.x - v.x) * factor,
      y: wp.y - (wp.y - v.y) * factor,
      width: v.width * factor,
      height: v.height * factor,
    }));
  }, [viewBox]);

  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const t0 = e.touches[0]!;
      const t1 = e.touches[1]!;
      const dist = Math.sqrt((t1.clientX - t0.clientX) ** 2 + (t1.clientY - t0.clientY) ** 2);
      pinchRef.current = { initialDist: dist, initialVB: { ...viewBox } };
    }
  }, [viewBox]);

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (e.touches.length === 2 && pinchRef.current) {
      const t0 = e.touches[0]!;
      const t1 = e.touches[1]!;
      const dist = Math.sqrt((t1.clientX - t0.clientX) ** 2 + (t1.clientY - t0.clientY) ** 2);
      const scale = pinchRef.current.initialDist / dist;
      const iv = pinchRef.current.initialVB;
      const cx = iv.x + iv.width / 2;
      const cy = iv.y + iv.height / 2;
      const nw = iv.width * scale;
      const nh = iv.height * scale;
      setViewBox({ x: cx - nw / 2, y: cy - nh / 2, width: nw, height: nh });
    }
  }, []);

  const handleTouchEnd = useCallback(() => { pinchRef.current = null; }, []);

  const fromNode = drawingEdge ? floorNodes.find(n => n.id === drawingEdge.fromNodeId) : null;

  return (
    <svg
      ref={svgRef}
      viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
      style={{ width: '100%', height: '100%', touchAction: 'none', background: '#f8fafc' }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onWheel={handleWheel}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      <Grid viewBox={viewBox} grid={project.grid} />
      <EdgeLayer edges={floorEdges} nodes={floorNodes} selectedEdgeIds={selection.edgeIds} />
      <NodeLayer nodes={floorNodes} selectedNodeIds={selection.nodeIds} dragState={dragState} />
      <ItemLayer items={floorItems} />
      <SelectionOverlay boxSelectState={boxSelectState} />
      <SnapGuides guides={snapGuides} />
      {fromNode && drawingEdge && (
        <line
          x1={fromNode.x} y1={fromNode.y}
          x2={drawingEdge.cursorPos.x} y2={drawingEdge.cursorPos.y}
          stroke="#3b82f6" strokeWidth={0.05} strokeDasharray="0.1 0.05"
        />
      )}
    </svg>
  );
}
