import { useStore } from '../../store';
import { createDeleteNodeCommand, createDeleteEdgeCommand } from '../../engine/commands';

export function PropertyPanel() {
  const selection = useStore(s => s.selection);
  const project = useStore(s => s.project);
  const applyCommand = useStore(s => s.applyCommand);
  const showPropertyPanel = useStore(s => s.showPropertyPanel);

  const hasSelection = selection.nodeIds.length > 0 || selection.edgeIds.length > 0 || selection.itemIds.length > 0;
  if (!hasSelection || !showPropertyPanel) return null;

  const selectedNode = selection.nodeIds.length === 1
    ? project.nodes.find(n => n.id === selection.nodeIds[0])
    : null;
  const selectedEdge = selection.edgeIds.length === 1
    ? project.links.find(e => e.id === selection.edgeIds[0])
    : null;

  const handleDelete = () => {
    for (const nodeId of selection.nodeIds) {
      applyCommand(createDeleteNodeCommand(nodeId));
    }
    for (const edgeId of selection.edgeIds) {
      applyCommand(createDeleteEdgeCommand(edgeId));
    }
  };

  return (
    <div style={{
      position: 'absolute',
      right: 8,
      top: 56,
      width: 200,
      background: 'white',
      borderRadius: 8,
      padding: 12,
      boxShadow: '0 2px 12px rgba(0,0,0,0.15)',
      zIndex: 10,
      fontSize: 13,
    }}>
      <div style={{ fontWeight: 600, marginBottom: 8, color: '#1e293b' }}>Properties</div>

      {selectedNode && (
        <div>
          <div style={{ color: '#64748b', marginBottom: 4 }}>Node</div>
          <div>Kind: {selectedNode.kind}</div>
          <div>X: {selectedNode.x.toFixed(2)}</div>
          <div>Y: {selectedNode.y.toFixed(2)}</div>
        </div>
      )}

      {selectedEdge && (
        <div>
          <div style={{ color: '#64748b', marginBottom: 4 }}>Edge</div>
          <div>Kind: {selectedEdge.kind}</div>
          <div>Bidir: {selectedEdge.bidir ? 'Yes' : 'No'}</div>
        </div>
      )}

      {!selectedNode && !selectedEdge && (
        <div style={{ color: '#64748b' }}>
          {selection.nodeIds.length} nodes, {selection.edgeIds.length} edges selected
        </div>
      )}

      <button
        onClick={handleDelete}
        style={{
          marginTop: 8,
          width: '100%',
          padding: '6px 0',
          border: '1px solid #fecaca',
          borderRadius: 4,
          background: '#fef2f2',
          color: '#dc2626',
          fontSize: 12,
          cursor: 'pointer',
        }}
      >
        Delete Selected
      </button>
    </div>
  );
}
