import { memo } from 'react';
import type { Item } from '../../types';
import { COLORS, ITEM_SIZE } from '../../utils/constants';

interface ItemLayerProps {
  items: Item[];
}

function getItemPosition(item: Item): { x: number; y: number } | null {
  if (item.anchor.type === 'coordinate') return { x: item.anchor.x, y: item.anchor.y };
  return null;
}

export const ItemLayer = memo(function ItemLayer({ items }: ItemLayerProps) {
  return (
    <g>
      {items.map(item => {
        const pos = getItemPosition(item);
        if (!pos) return null;
        const w = ITEM_SIZE.width;
        const h = ITEM_SIZE.depth;
        const color = COLORS.item[item.type];

        return (
          <g key={item.id} transform={`translate(${pos.x},${pos.y})`}>
            <rect x={-w / 2} y={-h / 2} width={w} height={h}
              fill={color} fillOpacity={0.2} stroke={color} strokeWidth={0.04} rx={0.08} />
            {item.type === 'stairs' && (
              <>
                <line x1={-w * 0.3} y1={-h * 0.2} x2={w * 0.3} y2={-h * 0.2} stroke={color} strokeWidth={0.03} />
                <line x1={-w * 0.3} y1={0} x2={w * 0.3} y2={0} stroke={color} strokeWidth={0.03} />
                <line x1={-w * 0.3} y1={h * 0.2} x2={w * 0.3} y2={h * 0.2} stroke={color} strokeWidth={0.03} />
              </>
            )}
            {item.type === 'elevator' && (
              <>
                <line x1={0} y1={-h * 0.3} x2={0} y2={h * 0.1} stroke={color} strokeWidth={0.04} />
                <polygon points="-0.1,-0.15 0.1,-0.15 0,-0.3" fill={color} />
                <polygon points="-0.1,0.15 0.1,0.15 0,0.3" fill={color} />
              </>
            )}
          </g>
        );
      })}
    </g>
  );
});
