import { memo } from 'react';
import type { Grid as GridType } from '../../types';
import { COLORS } from '../../utils/constants';

interface GridProps {
  viewBox: { x: number; y: number; width: number; height: number };
  grid: GridType;
}

export const Grid = memo(function Grid({ viewBox, grid }: GridProps) {
  const lines: JSX.Element[] = [];

  // Minor grid (snap)
  const snapStartX = Math.floor(viewBox.x / grid.snap) * grid.snap;
  const snapEndX = viewBox.x + viewBox.width;
  const snapStartY = Math.floor(viewBox.y / grid.snap) * grid.snap;
  const snapEndY = viewBox.y + viewBox.height;

  for (let x = snapStartX; x <= snapEndX; x += grid.snap) {
    lines.push(
      <line key={`sx${x}`} x1={x} y1={viewBox.y} x2={x} y2={snapEndY}
        stroke={COLORS.grid} strokeWidth={0.02} />
    );
  }
  for (let y = snapStartY; y <= snapEndY; y += grid.snap) {
    lines.push(
      <line key={`sy${y}`} x1={viewBox.x} y1={y} x2={snapEndX} y2={y}
        stroke={COLORS.grid} strokeWidth={0.02} />
    );
  }

  // Major grid (unit)
  const unitStartX = Math.floor(viewBox.x / grid.unit) * grid.unit;
  const unitEndX = Math.ceil(snapEndX / grid.unit) * grid.unit;
  const unitStartY = Math.floor(viewBox.y / grid.unit) * grid.unit;
  const unitEndY = Math.ceil(snapEndY / grid.unit) * grid.unit;

  for (let x = unitStartX; x <= unitEndX; x += grid.unit) {
    lines.push(
      <line key={`mx${x}`} x1={x} y1={viewBox.y} x2={x} y2={snapEndY}
        stroke={COLORS.gridMajor} strokeWidth={0.04} />
    );
  }
  for (let y = unitStartY; y <= unitEndY; y += grid.unit) {
    lines.push(
      <line key={`my${y}`} x1={viewBox.x} y1={y} x2={snapEndX} y2={y}
        stroke={COLORS.gridMajor} strokeWidth={0.04} />
    );
  }

  // Origin cross
  lines.push(<line key="ox" x1={viewBox.x} y1={0} x2={snapEndX} y2={0} stroke="#94a3b8" strokeWidth={0.06} />);
  lines.push(<line key="oy" x1={0} y1={viewBox.y} x2={0} y2={snapEndY} stroke="#94a3b8" strokeWidth={0.06} />);

  return <g>{lines}</g>;
});
